package com.wartec.wartecmod.port;

import com.wartec.wartecmod.port.planning.*;
import java.util.*;
import net.minecraft.nbt.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class PlanningDomainTest {
    @Test public void namedEmptyDraftCanBeSavedAndReloadedBeforeAddingSteps(){PlanningWorldData data=new PlanningWorldData();AttackOperation op=plan();op.steps.clear();assertEquals("",data.saveDraft(op,op.scope,op.author,0));assertEquals("steps",op.validate());PlanningWorldData restored=new PlanningWorldData();restored.readFromNBT(data.writeToNBT(new NBTTagCompound()));assertEquals(op.title,restored.operations.get(op.id).title);assertEquals(0,restored.operations.get(op.id).steps.size());}
    @Test public void pauseShiftsScheduleWithoutInventingEmissions(){AttackOperation op=plan();op.started=100;op.pausedAt=200;AttackOperation.Step step=op.steps.get(0);step.accepted=150;step.actual=180;step.nextAttempt=210;op.resumeClock(400);assertEquals(100,op.started);assertEquals(200,op.clockOffset);assertEquals(150,step.accepted);assertEquals(180,step.actual);assertEquals(410,step.nextAttempt);assertEquals(0,step.emitted);assertEquals(-1,step.completed);assertEquals(-1,op.pausedAt);assertEquals(200,AttackOperation.read(op.write()).clockOffset);}
    @Test public void iffWhitelistIsPersistentDirectionalAndDoesNotGrantIntelAccess(){DefenseRelations data=new DefenseRelations();assertEquals("",data.change("alpha","beta",true));assertTrue(data.friendly("alpha","beta"));assertFalse(data.friendly("beta","alpha"));assertFalse(PlanningAccessPolicy.same("team:alpha","team:beta"));DefenseRelations restored=new DefenseRelations();restored.readFromNBT(data.writeToNBT(new NBTTagCompound()));assertTrue(restored.friendly("alpha","beta"));assertEquals("team",data.change("alpha","none",true));assertEquals("",restored.change("alpha","beta",false));assertFalse(restored.friendly("alpha","beta"));}
    @Test public void eventFeedIncludesIdentificationFailureAndConfirmedBreakthrough(){DefenseBattleLog log=new DefenseBattleLog();UUID target=UUID.randomUUID(),shot=UUID.randomUUID();log.track(target,10);log.targets.get(target).setString("Name","Smerch");log.targets.get(target).setInteger("Tier",1);log.shot(shot,"buk","Buk",target,20);log.outcome(shot,target,false,40);log.targetOutcome(target,"breakthrough",80);assertEquals(3,log.events().size());assertEquals("identified",log.events().get(0).getString("Outcome"));assertEquals("failed",log.events().get(1).getString("Outcome"));assertEquals("Smerch",log.events().get(1).getString("TargetName"));assertEquals(1,log.summary("").getInteger("Failed"));assertEquals(1,log.summary("").getInteger("Breakthrough"));assertEquals(0,log.summary("").getInteger("Flying"));}
    @Test public void sensorArchiveViewportIsBoundedAndDoesNotMoveContacts(){TeamIntelData data=new TeamIntelData();UUID sensor=UUID.randomUUID();for(int i=-30;i<30;i++)for(int z=-30;z<30;z++)data.cell(i,z,64,0x456745,10,"SENSOR_SAR",sensor);data.contact("enemy","Launcher","platform",100,64,100,.8F,20,"SENSOR_SAR",sensor);NBTTagCompound view=data.viewport(0,0,512);assertEquals(1296,view.getIntArray("Terrain").length);assertTrue(view.getTagList("Cells",10).tagCount()<=256);assertEquals(100,view.getTagList("Contacts",10).getCompoundTagAt(0).getDouble("X"),.001);assertEquals(20,view.getTagList("Contacts",10).getCompoundTagAt(0).getLong("Seen"));}
    @Test public void detectedButUnengagedThreatsRemainUnknown(){DefenseBattleLog log=new DefenseBattleLog();UUID target=UUID.randomUUID();log.track(target,10);log.track(target,11);assertEquals(0,log.summary("").getInteger("Launched"));assertEquals(1,log.summary("").getInteger("Unknown"));log.targetOutcome(target,"breakthrough",20);assertEquals(1,log.summary("").getInteger("Breakthrough"));}
    @Test public void routeNbtIsWhitelistedAndCoordinatesAreChecked(){AttackOperation o=plan();NBTTagCompound route=new NBTTagCompound();route.setInteger("X",10);route.setInteger("Y",40);route.setInteger("Z",20);route.setString("UnknownPayload","discard");o.steps.get(0).route.appendTag(route);AttackOperation clean=AttackOperation.read(o.write());assertFalse(clean.steps.get(0).route.getCompoundTagAt(0).hasKey("UnknownPayload"));assertEquals("",clean.validate());clean.steps.get(0).route.getCompoundTagAt(0).setInteger("X",Integer.MAX_VALUE);assertEquals("coordinates",clean.validate());}
    private AttackOperation plan(){AttackOperation o=new AttackOperation();o.scope="team:alpha";o.author=UUID.randomUUID();o.title="Combined operation";AttackOperation.Step s=new AttackOperation.Step();s.asset="e:"+UUID.randomUUID();s.x=100;s.y=64;s.z=-200;o.steps.add(s);return o;}
    @Test public void unteamedPlayersHaveDifferentPrivateScopes(){UUID a=UUID.randomUUID(),b=UUID.randomUUID();assertFalse(PlanningAccessPolicy.same(PlanningAccessPolicy.scope("",a),PlanningAccessPolicy.scope("",b)));assertFalse(PlanningAccessPolicy.same("",""));assertFalse(PlanningAccessPolicy.same("team:alpha","team:beta"));assertTrue(PlanningAccessPolicy.same(PlanningAccessPolicy.scope("alpha",a),PlanningAccessPolicy.scope("alpha",b)));}
    @Test public void dependencyGraphRejectsCyclesAndDanglingReferences(){AttackOperation o=plan();AttackOperation.Step a=o.steps.get(0),b=new AttackOperation.Step();b.asset=a.asset;o.steps.add(b);a.after=b.id;b.after=a.id;assertEquals("cycle",o.validate());b.after=null;assertEquals("",o.validate());b.after=UUID.randomUUID();assertEquals("dependency",o.validate());}
    @Test public void countsCoordinatesAndClockAreValidatedBeforeAdmission(){AttackOperation o=plan();AttackOperation.Step s=o.steps.get(0);s.count=0;assertEquals("limits",o.validate());s.count=1;s.offset=-1;assertEquals("limits",o.validate());s.offset=0;s.y=256;assertEquals("coordinates",o.validate());s.y=64;s.x=Integer.MIN_VALUE;assertEquals("coordinates",o.validate());}
    @Test public void eventTimesAreNotManufacturedByAcceptance(){AttackOperation.Step s=new AttackOperation.Step();s.accepted=100;assertEquals(100,s.eventTime(AttackOperation.Event.ACCEPTED));assertEquals(-1,s.eventTime(AttackOperation.Event.ACTUAL));assertEquals(-1,s.eventTime(AttackOperation.Event.COMPLETE));s.actual=140;assertEquals(140,s.eventTime(AttackOperation.Event.ACTUAL));}
    @Test public void snapshotAndTemplatePreserveSettingsButNeverReplayIdentities(){AttackOperation o=plan();AttackOperation.Step a=o.steps.get(0),b=new AttackOperation.Step();b.asset=a.asset;b.after=a.id;b.offset=70;b.slot=3;b.count=2;b.interval=15;b.group="wave2";o.steps.add(b);a.phase=AttackOperation.Phase.DONE;a.actual=120;a.flights.add(UUID.randomUUID());o.state=AttackOperation.State.COMPLETE;o.started=90;
        AttackOperation restored=AttackOperation.read(o.write());assertEquals(o.id,restored.id);assertEquals(a.actual,restored.steps.get(0).actual);assertEquals(a.flights,restored.steps.get(0).flights);
        AttackOperation copy=o.template();assertNotEquals(o.id,copy.id);assertNotEquals(a.id,copy.steps.get(0).id);assertEquals(copy.steps.get(0).id,copy.steps.get(1).after);assertEquals(70,copy.steps.get(1).offset);assertEquals(3,copy.steps.get(1).slot);assertEquals(-1,copy.started);assertEquals(AttackOperation.Phase.PENDING,copy.steps.get(0).phase);assertTrue(copy.steps.get(0).flights.isEmpty());}
    @Test public void draftRevisionAndScopeRejectConcurrentOrForeignWrites(){PlanningWorldData d=new PlanningWorldData();AttackOperation a=plan();assertEquals("",d.saveDraft(a,a.scope,a.author,0));AttackOperation first=AttackOperation.read(a.write()),second=AttackOperation.read(a.write());assertEquals("",d.saveDraft(first,first.scope,first.author,1));assertEquals("revision",d.saveDraft(second,second.scope,second.author,1));assertEquals("revision",d.saveDraft(second,"team:beta",second.author,2));assertEquals(2,d.operations.get(a.id).revision);}
    @Test public void persistedPlansRetainAcceptedShotsAndUnloadedTelemetry(){PlanningWorldData d=new PlanningWorldData();AttackOperation o=plan();o.state=AttackOperation.State.RUNNING;AttackOperation.Step s=o.steps.get(0);s.phase=AttackOperation.Phase.ACCEPTED;s.accepted=100;s.emitted=1;s.actual=111;s.flights.add(UUID.randomUUID());d.operations.put(o.id,o);PlanningAsset a=new PlanningAsset();a.key=s.asset;a.scope=o.scope;a.loaded=true;d.assets.put(a.key,a);PlanningWorldData restored=new PlanningWorldData();restored.readFromNBT(d.writeToNBT(new NBTTagCompound()));assertEquals(AttackOperation.Phase.ACCEPTED,restored.operations.get(o.id).steps.get(0).phase);assertEquals(1,restored.operations.get(o.id).steps.get(0).emitted);assertFalse(restored.assets.get(a.key).loaded);}
    @Test public void intelRemainsAStoredObservationAndOnlyCoveredCellsAreRechecked(){TeamIntelData d=new TeamIntelData();UUID source=UUID.randomUUID();d.contact("a","Launcher","platform",8,64,8,.8F,100,"SENSOR_SAR",source);d.contact("b","Launcher","platform",1000,64,1000,.8F,100,"SENSOR_SAR",source);NBTTagCompound original=d.write();d.resurvey(0,0,Collections.emptySet(),200);assertFalse(d.contacts.get("a").getBoolean("Confirmed"));assertTrue(d.contacts.get("b").getBoolean("Confirmed"));assertEquals(100,d.contacts.get("a").getLong("Seen"));assertTrue(TeamIntelData.read(original).contacts.get("a").getBoolean("Confirmed"));}
    @Test public void defenseStatisticsDeduplicateActualShotsAndTargets(){DefenseBattleLog log=new DefenseBattleLog();UUID target=UUID.randomUUID(),one=UUID.randomUUID(),two=UUID.randomUUID();log.shot(one,"buk","Buk",target,10);log.shot(one,"buk","Buk",target,10);log.shot(two,"tor","Tor",target,12);assertEquals(2,log.summary("").getInteger("Launched"));assertEquals(-1,log.summary("").getDouble("Rate"),.001);log.outcome(one,target,true,50);log.outcome(two,target,true,51);log.targetOutcome(target,"breakthrough",52);assertEquals(1,log.summary("").getInteger("Intercepted"));assertEquals(0,log.summary("").getInteger("Breakthrough"));assertEquals(100,log.summary("").getDouble("Rate"),.001);assertEquals(1,log.summary("buk").getInteger("Launched"));}
    @Test public void failedShotDoesNotImplyTargetBreakthrough(){DefenseBattleLog log=new DefenseBattleLog();UUID target=UUID.randomUUID(),shot=UUID.randomUUID();log.shot(shot,"pvo","PVO",target,10);log.outcome(shot,target,false,40);assertEquals(1,log.summary("").getInteger("Unknown"));assertEquals(-1,log.summary("").getDouble("Rate"),.001);log.targetOutcome(target,"breakthrough",80);assertEquals(0,log.summary("").getDouble("Rate"),.001);DefenseBattleLog restored=DefenseBattleLog.read(log.write());assertEquals(1,restored.summary("").getInteger("Breakthrough"));}
    @Test public void boundedIntelAndLedgerEvictOldestRatherThanGrowingForever(){TeamIntelData intel=new TeamIntelData();UUID source=UUID.randomUUID();for(int i=0;i<4300;i++)intel.cell(i,0,64,0xFF0000,i,"SENSOR_SAR",source);assertEquals(4096,intel.cells.size());DefenseBattleLog log=new DefenseBattleLog();for(int i=0;i<2100;i++)log.shot(UUID.randomUUID(),"pvo","PVO",UUID.randomUUID(),i);assertEquals(2048,log.shots.size());assertEquals(2048,log.targets.size());}
}
